
const fs = require('fs/promises');
const path = require('path');
const yaml = require('js-yaml');

// Directory containing the YAML files generated by lore-yaml-merge.js
const INPUT_DIR_PATH = path.join(__dirname, '../content/seasons');
// Directory for the final escaped YAML output
const OUTPUT_DIR_PATH = path.join(__dirname, 'escaped-yaml-output');

class WavelengthYamlFlowUpdater {
  constructor() {
    this.updatedCount = 0;
  }

  /**
   * Recursively traverses an object and escapes all string values.
   * This converts multi-line strings into a single-line string with explicit
   * escaped newlines (\n) and escaped double quotes (\").
   * @param {Object|Array|string} data The object, array, or string to traverse/escape.
   * @returns {Object|Array|string} The modified structure.
   */
  escapeStrings(data) {
    if (typeof data === 'string') {
      // Replace all newlines with the literal sequence \n
      let escaped = data.replace(/\r?\n/g, '\\n');
      
      // Replace double quotes with escaped double quotes
      // This forces js-yaml to use single quotes on dump, or dump with the literal escaped double quotes
      escaped = escaped.replace(/"/g, '\\"');
      
      // Remove leading/trailing whitespace around newlines created by js-yaml dump/load process
      escaped = escaped.replace(/\\n\s+/g, '\\n').trim();
      
      return escaped;
    }

    if (Array.isArray(data)) {
      return data.map(item => this.escapeStrings(item));
    }

    if (typeof data === 'object' && data !== null) {
      const newObject = {};
      for (const key in data) {
        if (data.hasOwnProperty(key)) {
          // Recursively process the value
          newObject[key] = this.escapeStrings(data[key]);
        }
      }
      return newObject;
    }

    return data;
  }

  /**
   * Reads all YAML files, applies escaping, and writes the modified structure back as new YAML files.
   */
  async processFiles() {
    const files = await fs.readdir(INPUT_DIR_PATH);
    const yamlFiles = files.filter(file => file.endsWith('.yaml'));
    
    console.log(`\n🔍 Found ${yamlFiles.length} YAML files to process...`);

    // 1. Ensure the output directory exists
    try {
      await fs.mkdir(OUTPUT_DIR_PATH, { recursive: true });
      console.log(`   ✅ Output directory ensured: ${OUTPUT_DIR_PATH}`);
    } catch (error) {
      console.error(`   ❌ Failed to create output directory: ${OUTPUT_DIR_PATH}`, error.message);
      process.exit(1);
    }
    
    for (const filename of yamlFiles) {
      const inputPath = path.join(INPUT_DIR_PATH, filename);
      const outputPath = path.join(OUTPUT_DIR_PATH, filename);
      console.log(`\n   Processing: ${filename}`);

      try {
        const fileContent = await fs.readFile(inputPath, 'utf8');
        let seasonData = yaml.load(fileContent);
        
        // --- Core Escaping Logic ---
        // Escape all strings in the entire structure
        seasonData = this.escapeStrings(seasonData);
        // ---------------------------
        
        // Dump the modified object to a new YAML string
        // Setting lineWidth: -1 is crucial to ensure strings are written on a single line
        const yamlString = yaml.dump(seasonData, { indent: 2, lineWidth: -1 });

        // Write the new escaped YAML file
        await fs.writeFile(outputPath, yamlString, 'utf8');
        
        this.updatedCount++;
        console.log(`   ✅ Escaped file written to: ${outputPath}`);

      } catch (error) {
        console.error(`   ❌ Error processing ${filename}:`, error.message);
      }
    }
  }

  /**
   * Main execution function.
   */
  async runFlowUpdate() {
    console.log('🌊 WAVELENGTH LORE FLOW YAML UPDATER (YAML $\rightarrow$ Escaped YAML)');
    console.log('==================================================================');

    try {
      // 1. Process files and escape content
      await this.processFiles();
      
      console.log(`\n🎉 Escaping complete! ${this.updatedCount} YAML files with flow-style strings saved to: ${OUTPUT_DIR_PATH}`);
      console.log('NOTE: The multi-line strings are now converted to single-line scalars with explicit \\n and \\" escapes.');
    } catch (error) {
      console.error('\n🛑 A fatal error occurred during the escaping process:', error.message);
      console.log(`Please ensure the directory '${INPUT_DIR_PATH}' exists and contains YAML files.`);
    }
  }
}

// CLI execution for the flow updater
async function main() {
  const flowUpdater = new WavelengthYamlFlowUpdater();
  await flowUpdater.runFlowUpdate();
}

if (require.main === module) {
  main().catch(console.error);
}

